  return {"rc":p.returncode,"stdout":p.stdout,"stderr":p.stderr}
 except Exception as e: return {"error":str(e)}
def tail_records(path,limit=65536):
 if not path.is_file(): return {"bytes":0,"records":[]}
 size=path.stat().st_size
 with path.open("rb") as f:
  offset=max(0,size-limit); f.seek(offset); lines=f.read().splitlines()
 if offset and lines: lines=lines[1:]
 records=[]
 for line in lines:
  try: records.append(json.loads(line))
  except ValueError: pass
 return {"bytes":size,"records":records}
