   except OSError as e: proc={"error":str(e)}
  containers[x["Name"].lstrip("/")]={"id":x["Id"],"image":x["Image"],"status":x["State"]["Status"],"started_at":x["State"]["StartedAt"],"restart_count":x["RestartCount"],"pid":pid,"command":x["Config"]["Cmd"],"mounts":x["Mounts"],"proc":proc}
